            group_by += " HAVING COUNT(*) > $minimum"
        order_by = 'order by cnt desc' if sort_by_count else ''
        query = f"""
            select work_id, count(*) as cnt
            from bookshelves_books
            {where} {group_by} {order_by}
            limit $limit offset $offset"""
        logger.info("Query: %s", query)
